<?php require_once '../includes/role.php';requireRole('admin');require_once '../config/database.php';require_once '../includes/helpers.php';require_once '../includes/csrf.php';$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){ $name=trim($_POST['name']??'');$part=trim($_POST['part_number']??'');$stock=(int)$_POST['stock'];$price=(float)$_POST['price'];if($name===''||$stock<0||$price<0)$error='Data sparepart tidak valid.';else{$s=$id?$pdo->prepare('UPDATE spareparts SET name=?,part_number=?,stock=?,price=? WHERE id=?'):$pdo->prepare('INSERT INTO spareparts(name,part_number,stock,price) VALUES(?,?,?,?)');$s->execute($id?[$name,$part?:null,$stock,$price,$id]:[$name,$part?:null,$stock,$price]);$success=$id?'Sparepart diperbarui.':'Sparepart ditambahkan.';}}elseif($action==='toggle'){$s=$pdo->prepare("UPDATE spareparts SET status=IF(status='active','inactive','active') WHERE id=?");$s->execute([$id]);$success='Status sparepart diperbarui.';}}$rows=$pdo->query('SELECT * FROM spareparts ORDER BY status DESC,name')->fetchAll();$edit=null;if(isset($_GET['edit']))foreach($rows as $x)if($x['id']==(int)$_GET['edit'])$edit=$x;$pageTitle='Sparepart';require '../includes/admin_header.php';?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="success"><?=e($success)?></div><?php endif;?><div class="two-column"><section class="panel"><div class="panel-heading"><h2><?= $edit?'Edit':'Tambah'?> Sparepart</h2></div><form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Nama<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Part Number<input name="part_number" value="<?=e($edit['part_number']??'')?>"></label><label>Stok<input type="number" name="stock" min="0" value="<?=e($edit['stock']??0)?>" required></label><label>Harga<input type="number" name="price" min="0" step="0.01" value="<?=e($edit['price']??0)?>" required></label><button>Simpan</button></form></section><section class="panel"><div class="table-wrap"><table class="data-table"><tr><th>Part</th><th>Stok</th><th>Harga</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['name'])?><small><?=e($x['part_number']?:'-')?></small></td><td><?=$x['stock']?></td><td><?=rupiah($x['price'])?></td><td><span class="badge badge-<?=$x['status']?>"><?=e($x['status'])?></span></td><td><a class="button small secondary" href="spareparts.php?edit=<?=$x['id']?>">Edit</a><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="small">Toggle</button></form></td></tr><?php endforeach;?></table></div></section></div><?php require '../includes/admin_footer.php';?>